"""Generate THIRD_PARTY_NOTICES.md from the ymind-app runtime dependency graph.

Usage: python .github/scripts/third_party_notices.py [--check]
"""

from __future__ import annotations

import argparse
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUTPUT = ROOT / "THIRD_PARTY_NOTICES.md"
ROOT_PACKAGE = "ymind-app"

HEADER = """# Third-party notices

yMind is licensed under the [EUPL-1.2](LICENSE.md). It is built with the
open-source components listed below, which remain under their own licenses.
Their copyright notices and full license texts are distributed with each
component's source code (see the linked repositories or
[crates.io](https://crates.io)). All listed licenses are compatible with
distributing yMind under the EUPL-1.2. Where a component offers a choice of
licenses, yMind uses it under the permissive option (for example MIT or
Apache-2.0 instead of LGPL/GPL).

This file is generated by `python .github/scripts/third_party_notices.py`;
CI fails when it is out of date. It covers the runtime dependencies of the
`ymind` application on all supported platforms; build-only and test-only tools
are not redistributed and are not listed.

## Embedded fonts

The user interface embeds egui's default fonts (crate `epaint_default_fonts`):

| Font | License |
|---|---|
| Ubuntu Light | Ubuntu Font Licence 1.0 |
| Hack | MIT / Bitstream Vera License |
| Noto Emoji | SIL Open Font License 1.1 |
| emoji-icon-font | SIL Open Font License 1.1 |

## Notable licenses

- **MPL-2.0** (`option-ext`): file-level copyleft. The unmodified source is
  available from the linked repository.
- **CDLA-Permissive-2.0** (`webpki-roots`): data license for the bundled
  Mozilla root certificate list.
- **Unicode-3.0** (ICU4X crates): Unicode data and software license.

## Rust crates
"""


def cargo_metadata() -> dict:
    out = subprocess.run(
        ["cargo", "metadata", "--format-version", "1", "--locked"],
        cwd=ROOT,
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    return json.loads(out)


def runtime_packages(meta: dict) -> list[dict]:
    packages = {p["id"]: p for p in meta["packages"]}
    workspace = set(meta["workspace_members"])
    nodes = {n["id"]: n for n in meta["resolve"]["nodes"]}
    start = next(i for i in workspace if packages[i]["name"] == ROOT_PACKAGE)
    seen: set[str] = set()
    stack = [start]
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        for dep in nodes[current]["deps"]:
            if any(k["kind"] is None for k in dep["dep_kinds"]):
                stack.append(dep["pkg"])
    return sorted(
        (packages[i] for i in seen if i not in workspace),
        key=lambda p: (p["name"].lower(), p["version"]),
    )


def render(packages: list[dict]) -> str:
    rows = ["| Crate | Version | License | Source |", "|---|---|---|---|"]
    for p in packages:
        license_ = (p.get("license") or "see license file").replace("|", "\\|")
        repo = p.get("repository") or f"https://crates.io/crates/{p['name']}"
        rows.append(f"| {p['name']} | {p['version']} | {license_} | <{repo}> |")
    return HEADER + "\n" + f"{len(packages)} crates.\n\n" + "\n".join(rows) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the file is stale")
    args = parser.parse_args()
    text = render(runtime_packages(cargo_metadata()))
    if args.check:
        current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.exists() else ""
        if current.replace("\r\n", "\n") != text:
            print(f"{OUTPUT.name} is out of date; run {Path(__file__).name}", file=sys.stderr)
            return 1
        return 0
    OUTPUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUTPUT.name} ({len(text.splitlines())} lines)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
